INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Prüfung 1: Planen eines Softwareprodukts > IT-Sicherheit > Datensicherheit > Autorisierung
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Ist die Autorisierung notwendig, um den Zugriff auf sensible Daten nach der Authentifizierung zu regeln?', 2, '[{"text": "Ja", "correct": true, "because": "Autorisierung definiert, was ein authentifizierter Nutzer tun darf"}, {"text": "Nein", "correct": false, "because": "Ohne Autorisierung fehlt die Zugriffskontrolle"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Autorisierung ohne vorherige Authentifizierung erfolgen?', 2, '[{"text": "Nein", "correct": true, "because": "Autorisierung setzt eine verifizierte Identität voraus"}, {"text": "Ja", "correct": false, "because": "Identität muss erst bestätigt werden"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss die Autorisierung immer rollenbasierte Zugriffskontrolle (RBAC) verwenden?', 2, '[{"text": "Nein", "correct": true, "because": "Andere Modelle wie ACL sind ebenfalls möglich"}, {"text": "Ja", "correct": false, "because": "RBAC ist nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Autorisierungsmechanismen durch unzureichende Konfiguration umgangen werden?', 2, '[{"text": "Ja", "correct": true, "because": "Schlechte Implementierung kann Schwachstellen schaffen"}, {"text": "Nein", "correct": false, "because": "Risiko besteht"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Autorisierung dasselbe wie die Verschlüsselung von Daten?', 2, '[{"text": "Nein", "correct": true, "because": "Autorisierung regelt Zugriff, Verschlüsselung schützt Daten"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Konzepte"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolgt die Autorisierung primär?', 2, '[{"text": "Zugriffskontrolle", "correct": true, "because": "Regelt Berechtigungen nach Authentifizierung"}, {"text": "Identitätsprüfung", "correct": false, "because": "Aufgabe der Authentifizierung"}, {"text": "Datenverschlüsselung", "correct": false, "because": "Anderes Sicherheitsziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode wird häufig für die Autorisierung in Unternehmenssystemen verwendet?', 3, '[{"text": "Rollenbasierte Zugriffskontrolle (RBAC)", "correct": true, "because": "Effizient für viele Nutzer"}, {"text": "Direkte Passwortprüfung", "correct": false, "because": "Authentifizierungsmethode"}, {"text": "Biometrische Prüfung", "correct": false, "because": "Authentifizierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Mechanismus stellt sicher, dass ein Nutzer nur auf erlaubte Ressourcen zugreift?', 2, '[{"text": "Zugriffssteuerungslisten (ACL)", "correct": true, "because": "Definiert Berechtigungen pro Ressource"}, {"text": "Firewall", "correct": false, "because": "Netzwerkschutz"}, {"text": "CAPTCHA", "correct": false, "because": "Bot-Schutz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schwäche kann eine schlecht implementierte Autorisierung haben?', 2, '[{"text": "Zugriffsüberschreitung", "correct": true, "because": "Nutzer könnten unerlaubte Berechtigungen erhalten"}, {"text": "Langsame Verarbeitung", "correct": false, "because": "Nicht primäres Problem"}, {"text": "Hohe Kosten", "correct": false, "because": "Kosten sind sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip sollte bei der Autorisierung Priorität haben?', 2, '[{"text": "Least Privilege", "correct": true, "because": "Minimale Rechte für maximale Sicherheit"}, {"text": "Maximale Freiheit", "correct": false, "because": "Unsicher"}, {"text": "Einheitliche Berechtigungen", "correct": false, "because": "Weniger sicher"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Methoden können für die Autorisierung eingesetzt werden?', 4, '[{"text": "Rollenbasierte Zugriffskontrolle (RBAC)", "correct": true, "because": "Rollen definieren Rechte"}, {"text": "Attributbasierte Zugriffskontrolle (ABAC)", "correct": true, "because": "Attribute bestimmen Zugriff"}, {"text": "Zugriffssteuerungslisten (ACL)", "correct": true, "because": "Ressourcenspezifische Rechte"}, {"text": "Passwortlänge", "correct": false, "because": "Authentifizierungsmerkmal"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren erhöhen die Effektivität der Autorisierung?', 3, '[{"text": "Granulare Berechtigungen", "correct": true, "because": "Präzise Zugriffskontrolle"}, {"text": "Regelmäßige Überprüfung", "correct": true, "because": "Verhindert veraltete Rechte"}, {"text": "Least Privilege Prinzip", "correct": true, "because": "Minimiert Risiken"}, {"text": "Einfache Passwörter", "correct": false, "because": "Authentifizierung, nicht Autorisierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Bedrohungen können die Autorisierung gefährden?', 4, '[{"text": "Privilege Escalation", "correct": true, "because": "Erhöht Berechtigungen unbefugt"}, {"text": "Schlechte Konfiguration", "correct": true, "because": "Erlaubt ungewollten Zugriff"}, {"text": "Insider-Bedrohungen", "correct": true, "because": "Missbrauch bestehender Rechte"}, {"text": "Langsame Server", "correct": false, "because": "Kein Autorisierungsrisiko"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technologien unterstützen die Autorisierung?', 3, '[{"text": "OAuth", "correct": true, "because": "Delegiert Zugriffsberechtigungen"}, {"text": "LDAP", "correct": true, "because": "Verwaltet Rollen und Rechte"}, {"text": "RBAC-Systeme", "correct": true, "because": "Rollenbasierte Steuerung"}, {"text": "SMTP", "correct": false, "because": "E-Mail-Protokoll"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Prinzipien sollten bei der Autorisierung beachtet werden?', 3, '[{"text": "Least Privilege", "correct": true, "because": "Minimiert Risiken"}, {"text": "Trennung von Aufgaben", "correct": true, "because": "Verhindert Machtmissbrauch"}, {"text": "Auditierbarkeit", "correct": true, "because": "Ermöglicht Nachverfolgung"}, {"text": "Maximale Offenheit", "correct": false, "because": "Unsicher"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Autorisierung regelt die Zugriffsberechtigungen. b) Sie kann ohne Authentifizierung funktionieren.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Zugriff ja, Authentifizierung nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) RBAC ist eine gängige Autorisierungsmethode. b) Autorisierung ist dasselbe wie Verschlüsselung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "RBAC ja, Verschlüsselung nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Least Privilege reduziert Sicherheitsrisiken bei der Autorisierung. b) Autorisierung erfordert immer RBAC.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Least Privilege ja, RBAC optional"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Privilege Escalation ist ein Risiko der Autorisierung. b) Autorisierung kann ohne Konfiguration sicher sein.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Escalation ja, Konfiguration nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Autorisierung schützt sensible Daten durch Zugriffskontrolle. b) Sie ist unabhängig von der Authentifizierung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Zugriff ja, Authentifizierung Voraussetzung"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

